import json
import sqlite3


class Importer:
    def __init__(self, path):
        self.db = sqlite3.connect(path)
        self.db.executescript("""
            CREATE TABLE IF NOT EXISTS jobs (
                id TEXT PRIMARY KEY, next_index INTEGER NOT NULL, state TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS rows (
                job_id TEXT NOT NULL, row_index INTEGER NOT NULL, payload TEXT NOT NULL,
                PRIMARY KEY (job_id, row_index)
            );
            CREATE TABLE IF NOT EXISTS accepted (
                job_id TEXT NOT NULL, row_index INTEGER NOT NULL, payload TEXT NOT NULL,
                PRIMARY KEY (job_id, row_index)
            );
        """)

    def close(self):
        self.db.close()

    def create_job(self, job_id, rows):
        rows = list(rows)
        with self.db:
            self.db.execute("INSERT INTO jobs VALUES (?, 0, ?)",
                            (job_id, "ready" if rows else "completed"))
            self.db.executemany("INSERT INTO rows VALUES (?, ?, ?)",
                                [(job_id, i, json.dumps(row)) for i, row in enumerate(rows)])
        return self.snapshot(job_id)

    def snapshot(self, job_id):
        job = self.db.execute("SELECT next_index, state FROM jobs WHERE id = ?", (job_id,)).fetchone()
        if job is None:
            raise KeyError(job_id)
        values = self.db.execute("SELECT payload FROM accepted WHERE job_id = ? ORDER BY row_index", (job_id,))
        return {"next_index": job[0], "state": job[1], "accepted": [json.loads(row[0]) for row in values]}

    def run_batch(self, job_id, limit=2):
        if limit < 1:
            raise ValueError("limit must be positive")
        job = self.snapshot(job_id)
        if job["state"] == "completed":
            return job
        with self.db:
            pending = self.db.execute(
                "SELECT row_index, payload FROM rows WHERE job_id = ? AND row_index >= ? ORDER BY row_index LIMIT ?",
                (job_id, job["next_index"], limit),
            ).fetchall()
            for row_index, payload in pending:
                self.db.execute("INSERT INTO accepted VALUES (?, ?, ?)", (job_id, row_index, payload))
                self.db.execute("UPDATE jobs SET next_index = ? WHERE id = ?", (row_index + 1, job_id))
            total = self.db.execute("SELECT COUNT(*) FROM rows WHERE job_id = ?", (job_id,)).fetchone()[0]
            done = self.db.execute("SELECT next_index FROM jobs WHERE id = ?", (job_id,)).fetchone()[0]
            if done == total:
                self.db.execute("UPDATE jobs SET state = 'completed' WHERE id = ?", (job_id,))
        return self.snapshot(job_id)

